ALTER TABLE "business_reading" ADD CONSTRAINT "business_reading_shape" CHECK (("business_reading"."method" = 'model') = ("business_reading"."reason" is null and "business_reading"."model_id" is not null and "business_reading"."adapter_id" is not null and "business_reading"."adapter_version" is not null and "business_reading"."prompt_version" is not null) and ("business_reading"."method" <> 'rule-based' or ("business_reading"."evidence" = '[]'::jsonb and "business_reading"."reason" is not null and "business_reading"."model_id" is null and "business_reading"."adapter_id" is null and "business_reading"."adapter_version" is null and "business_reading"."prompt_version" is null)) and ("business_reading"."method" <> 'model' or (case when jsonb_typeof("business_reading"."evidence") = 'array' then jsonb_array_length("business_reading"."evidence") <= 200 else false end)));